<div id="geo-content" hidden>
<div class="geo-tabs" role="tablist" aria-label="متابعة ظهور الشركة"><button type="button" class="p-btn outline" id="geo-tab-results" role="tab" aria-controls="geo-pane-results" aria-selected="true" tabindex="0">النتائج</button><button type="button" class="p-btn outline" id="geo-tab-questions" role="tab" aria-controls="geo-pane-questions" aria-selected="false" tabindex="-1">الأسئلة</button><button type="button" class="p-btn outline" id="geo-tab-settings" role="tab" aria-controls="geo-pane-settings" aria-selected="false" tabindex="-1">بيانات الشركة</button></div>
<section id="geo-pane-results" role="tabpanel" aria-labelledby="geo-tab-results"><h3>ظهور شركتك في الأسبوع الحالي</h3><div id="geo-cards" class="geo-grid"></div><p id="geo-coverage" class="geo-muted"></p><div class="geo-box"><h3>الإجابات والمصادر</h3><p class="geo-muted">راجع مقتطف الإجابة وروابط المصادر للتأكد من النتيجة.</p><div id="geo-answers" class="geo-scroll"></div></div><details class="geo-box"><summary>تطور النتائج خلال آخر ٨ أسابيع</summary><div id="geo-trend" class="geo-scroll"></div></details><details class="geo-box"><summary>اقتراحات تحسين مبنية على النتائج</summary><div id="geo-tasks" class="geo-scroll"></div></details><p class="geo-muted">القياس عينة من إجابات البحث في وقت محدد، مش ضمان ظهور في تطبيقات الشات. ترتيب الاسم محسوب وسط الشركات المتابَعة فقط.</p></section>
<section id="geo-pane-questions" role="tabpanel" aria-labelledby="geo-tab-questions" hidden><div class="geo-head"><div><h3>٣. راجع الأسئلة ووافق على اللي يناسبك</h3><p class="geo-muted">الأسئلة بتتجهّز من كلمات البحث الحقيقية. كل سؤال لازم تحفظ موافقتك عليه عشان يدخل القياس الأسبوعي.</p></div><button type="button" class="p-btn" id="geo-generate">تجهيز أسئلة مقترحة</button></div><p id="geo-question-count" class="geo-muted"></p><div id="geo-questions"></div><a class="p-btn outline" id="geo-keywords" href="/keywords">إدارة الأسواق وكلمات البحث</a></section>
<section id="geo-pane-settings" role="tabpanel" aria-labelledby="geo-tab-settings" hidden><h3>أكد هوية شركتك</h3><p class="geo-muted">ابدأ بتأكيد الاسم والخدمات من بيانات الشركة. الأسماء البديلة والروابط هنا بتساعدنا نميّز شركتك عن الشركات المشابهة.</p><a href="/business-hub" class="p-btn outline">مراجعة بيانات الشركة</a><form id="geo-identity" class="geo-box"><label for="geo-aliases">أسماء بديلة لشركتك بالعربي أو الإنجليزي<textarea class="p-select" id="geo-aliases" name="aliases" maxlength="1000" placeholder="اسم واحد في كل سطر"></textarea></label><label for="geo-profiles">روابط صفحات شركتك الرسمية<textarea class="p-select" id="geo-profiles" name="profiles" maxlength="10000" placeholder="رابط كامل في كل سطر"></textarea></label><p class="geo-muted">تغيير الهوية يحتاج مراجعة الأسئلة والموافقة عليها من جديد.</p><button class="p-btn">حفظ الأسماء والروابط</button></form><details class="geo-box"><summary>اختياري: مسودة تعريف الموقع لمحركات الذكاء الاصطناعي</summary><p class="geo-muted">جهّز مسودة llms.txt من صفحات موقعك العامة. راجعها قبل النشر؛ الزر ده مش بينشرها على موقعك.</p><button type="button" class="p-btn outline" id="geo-llms">تجهيز المسودة</button><pre id="geo-llms-draft"></pre></details></section>
</div></section>
<script>
(()=>{const start=()=>{const el=id=>document.getElementById('geo-'+id);if(!el('root')||!window.Panel)return;let data=null,busy=false,sitesLoaded=false,active='results';const root=el('root'),rows=v=>Array.isArray(v)?v:[],labels={openai:'ChatGPT',gemini:'Gemini',perplexity:'Perplexity'},base=()=>({website_id:Number(el('site').value),market_id:Number(el('market').value)}),visible=r=>Number(r.market_id)===base().market_id;
const node=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
const parsed=(v,fallback)=>{if(v&&typeof v==='object')return v;try{const r=JSON.parse(v);return r&&typeof r==='object'?r:fallback;}catch{return fallback;}};
const message=(text,error=false)=>{el('message').textContent=text;el('message').hidden=!text;el('message').dataset.error=String(error);};
function gate(){root.setAttribute('aria-busy',String(busy));root.querySelectorAll('button,input,textarea,select').forEach(c=>c.disabled=busy);el('site').disabled=busy||!el('site').value;el('market').disabled=busy||!data||!el('market').value;for(const id of ['generate','llms'])el(id).disabled=busy||!data||!base().market_id;el('reload').textContent=busy?'جارٍ التحميل…':'تحديث النتائج';}
function tab(name,focus=false){active=name;for(const key of ['results','questions','settings']){el('pane-'+key).hidden=key!==name;el('tab-'+key).setAttribute('aria-selected',String(key===name));el('tab-'+key).tabIndex=key===name?0:-1;}if(focus)el('tab-'+name).focus();}
for(const name of ['results','questions','settings'])el('tab-'+name).onclick=()=>tab(name);
root.querySelector('[role=tablist]').onkeydown=e=>{const names=['results','questions','settings'];if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const i=names.indexOf(active);tab(e.key==='Home'?names[0]:e.key==='End'?names[2]:names[(i+(e.key==='ArrowLeft'?1:2))%3],true);};
function action(label,fn,href){const n=node(href?'a':'button',label,'p-btn outline');if(href)n.href=href;else{n.type='button';n.onclick=fn;}el('next-actions').append(n);}
function next(title,text){el('next-title').textContent=title;el('state').textContent=text;el('next-actions').replaceChildren();}
async function request(path,body){const r=await window.Panel.fetchJSON('/api/ai-visibility/'+path+(body===undefined?'?'+new URLSearchParams(base()):''),body===undefined?undefined:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...base(),...body,csrf_token:root.dataset.csrf})});if(!r?.success)throw Error(r?.error||r?.message||'تعذر إتمام الطلب. حاول تاني.');return r.data;}
async function work(fn,success=''){if(busy)return;busy=true;message('');gate();try{await fn();if(success)message(success);}catch(e){message(e.message||'تعذر إتمام الطلب. حاول تاني.',true);if(!data){next('تعذر تحميل البيانات','اختيار موقعك محفوظ. اضغط تحديث النتائج لإعادة المحاولة.');action('إعادة المحاولة',()=>work(load));}}finally{busy=false;gate();}}
function empty(dest,text){dest.replaceChildren(node('p',text,'geo-empty'));}
function table(id,list,cols,emptyText){const dest=el(id);if(!list.length){empty(dest,emptyText);return;}const t=node('table',undefined,'p-table'),tr=t.createTHead().insertRow();cols.forEach(c=>{const th=node('th',c[1]);th.scope='col';tr.append(th);});const body=t.createTBody();list.forEach(r=>{const tr=body.insertRow();cols.forEach(c=>{const td=tr.insertCell(),v=typeof c[0]==='function'?c[0](r):r[c[0]];if(v instanceof Node)td.append(v);else td.textContent=String(v??'غير متاح');});});dest.replaceChildren(t);}
const pct=v=>v===null||v===undefined||!Number.isFinite(Number(v))?'غير مقاس':(Number(v)*100).toFixed(1)+'%';
function sources(value){const box=node('div');for(const raw of rows(parsed(value,[]))){try{const u=new URL(typeof raw==='string'?raw:raw.url);if(!['https:','http:'].includes(u.protocol))continue;const a=node('a',u.hostname);a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';box.append(a,node('br'));}catch{}}if(!box.childNodes.length)box.textContent='مفيش مصدر متاح';return box;}
function draw(){const qs=rows(data.questions).filter(visible),approved=qs.filter(q=>Number(q.approved)===1).length,metrics=rows(data.metrics).filter(visible),answers=rows(data.answers).filter(visible);const waiting=approved>0;
if(!base().market_id){next('اختار سوق لموقعك','حدد البلد واللغة من إدارة الأسواق، وبعدها حدّث النتائج.');action('إدارة الأسواق وكلمات البحث',null,'/keywords?website_id='+base().website_id);}
else if(!qs.length){next('الخطوة التالية: جهّز أسئلة عملائك','أكد بيانات الشركة وكلمات البحث الحقيقية، وبعدها جهّز الأسئلة وراجعها.');action('مراجعة بيانات الشركة',null,'/business-hub');action('تجهيز الأسئلة',()=>{tab('questions');work(generate);});}
else if(!waiting){next('الخطوة التالية: راجع الأسئلة واحفظ موافقتك','الأسئلة غير المعتمدة مش بتدخل القياس. اختار الأسئلة المناسبة واحفظ كل سؤال.');action('مراجعة الأسئلة',()=>tab('questions'));}
else if(!metrics.length){next('أسئلتك المعتمدة جاهزة للقياس الأسبوعي',approved+' سؤال معتمد في السوق ده. النتائج هتظهر بعد تشغيل القياس المجدول؛ تحديث النتائج مش بيبدأ قياس جديد.');action('مراجعة الأسئلة',()=>tab('questions'));}
else{next('نتائج السوق متاحة للمراجعة','راجع الإجابات ومصادرها. تحديث النتائج بيعرض أحدث قياسات محفوظة، ومش بيبدأ قياس جديد.');action('عرض الإجابات والمصادر',()=>{tab('results');el('answers').scrollIntoView({behavior:'smooth',block:'center'});});}
el('cards').replaceChildren();for(const [name,status] of Object.entries(data.providers||{})){const card=node('article',undefined,'geo-box'),m=metrics.find(x=>x.provider===name);card.append(node('h3',status?.label||labels[name]||'خدمة بحث'));if(m){card.append(node('div',pct(m.share_of_voice),'geo-stat'),node('p','نسبة الإجابات اللي ذكرت شركتك'),node('p','اقتباس موقعك: '+pct(m.citation_rate),'geo-muted'),node('p',m.questions+' إجابة مقاسة','geo-muted'));}else card.append(node('p','لسه مفيش قياسات محفوظة للسوق ده.','geo-muted'));el('cards').append(card);}if(!el('cards').children.length)empty(el('cards'),'لسه مفيش نتائج لعرضها.');
el('coverage').textContent=metrics.length?'النسب من الإجابات المقاسة خلال الأسبوع الحالي، مش من كل إجابات الخدمة.':'عدم وجود قياس مش معناه إن نسبة ظهورك صفر.';
el('question-count').textContent=qs.length?approved+' سؤال معتمد من '+qs.length+' في السوق المختار.':'لسه مفيش أسئلة للسوق ده. جهّز كلمات البحث الحقيقية الأول، وبعدها اضغط تجهيز أسئلة مقترحة.';
el('questions').replaceChildren();if(qs.length){const set=rows(data.question_sets).find(visible)||{version:0,approved:0},form=node('div',undefined,'geo-box'),inputs=[],check=node('input'),approval=node('label',undefined,'geo-check'),button=node('button','حفظ الأسئلة','p-btn'),changed=()=>{button.textContent='حفظ التغييرات';};qs.forEach((q,i)=>{const label=node('label','السؤال '+(i+1)),input=node('textarea',undefined,'p-select');input.id='geo-question-'+q.id;label.htmlFor=input.id;input.value=q.question||'';input.maxLength=300;input.oninput=changed;inputs.push(input);form.append(label,input);});check.type='checkbox';check.checked=Number(set.approved)===1;check.onchange=changed;approval.append(check,document.createTextNode('راجعت الأسئلة دي وموافق على قياسها أسبوعيًا'));button.type='button';button.onclick=()=>work(async()=>{const list=inputs.map(i=>i.value.trim()).filter(Boolean);if(list.length<10||list.length>30)throw Error('لازم يكون عندك من 10 لـ 30 سؤال. امسح نص السؤال عشان تشيله.');await request('questions',{questions:list,version:Number(set.version),approved:check.checked});await load();},'تم حفظ الأسئلة وموقف الموافقة.');form.append(node('p','عشان تشيل سؤال، امسح نصه واحفظ.','geo-muted'),approval,button);el('questions').append(form);}if(!qs.length)empty(el('questions'),'ابدأ بتجهيز الأسئلة من كلمات البحث، وبعدها هتظهر هنا للمراجعة.');
table('answers',answers,[[r=>labels[r.provider]||'خدمة بحث','الخدمة'],['question','السؤال'],[r=>Number(r.mentioned_brand)?'تم ذكر الشركة':'لم تُذكر الشركة','ذكر شركتك'],[r=>r.cited_domain==null?'غير مقاس':Number(r.cited_domain)?'تم الاقتباس':'لم يتم الاقتباس','اقتباس موقعك'],[r=>sources(r.cited_urls),'المصادر'],['answer_excerpt','مقتطف الإجابة'],['checked_at','تاريخ القياس']],'بعد أول قياس، الإجابات ومصادرها هتظهر هنا.');
const trend=[];rows(data.trend).forEach(w=>rows(w.providers).filter(visible).forEach(p=>trend.push({...p,week:w.week})));table('trend',trend,[['week','الأسبوع'],[r=>labels[r.provider]||'خدمة بحث','الخدمة'],[r=>pct(r.share_of_voice),'نسبة الذكر'],[r=>pct(r.citation_rate),'الاقتباس']],'اتجاه النتائج بيتكوّن مع تراكم القياسات الأسبوعية.');
table('tasks',rows(data.tasks),[['title','المهمة'],['instructions','خطوات المراجعة'],[r=>sources([parsed(r.evidence_json,{}).url].filter(Boolean)),'المصدر'],[r=>({pending:'للمراجعة',verified:'تم التحقق',done:'مكتملة',dismissed:'تم استبعادها',applied:'تم التطبيق'}[r.status]||'للمراجعة'),'الحالة']],'مفيش اقتراحات تحسين متاحة حاليًا.');el('identity').elements.aliases.value=rows(data.aliases).slice(1).join('\n');el('identity').elements.profiles.value=rows(data.profile_urls).join('\n');el('keywords').href='/keywords?website_id='+base().website_id;el('content').hidden=false;tab(active);}
async function load(){data=null;el('content').hidden=true;el('llms-draft').textContent='';next('جارٍ تحميل حالة الموقع','بنحمّل الأسواق والأسئلة والقياسات المحفوظة…');if(!sitesLoaded){const r=await window.Panel.fetchJSON('/api/websites');if(!r?.success)throw Error(r?.error||'تعذر تحميل المواقع.');const sites=rows(r.data?.websites||r.data?.items||r.data);const previous=el('site').value||new URLSearchParams(location.search).get('website_id');el('site').replaceChildren(...sites.map(s=>new Option(s.name||s.domain||s.main_url||s.url||'موقعي',s.id)));if(sites.some(s=>String(s.id)===previous))el('site').value=previous;sitesLoaded=true;}if(!base().website_id){sitesLoaded=false;next('أضف موقعك عشان تبدأ','اربط موقعك بحسابك، وبعدها ارجع هنا لاختيار السوق وتجهيز الأسئلة.');action('إدارة المواقع',null,'/websites');return;}const previous=el('market').value;el('market').replaceChildren(new Option('جارٍ تحميل الأسواق…',''));try{data=await request('overview');}catch(e){el('market').replaceChildren(new Option('تعذر تحميل الأسواق',''));throw e;}const markets=rows(data.markets);el('market').replaceChildren(...markets.map(m=>new Option(m.label,m.id)));if(markets.some(m=>String(m.id)===previous))el('market').value=previous;if(!markets.length)el('market').append(new Option('مفيش سوق مضاف',''));draw();}
async function generate(){await request('generate',{});await load();}
el('site').onchange=()=>{el('market').replaceChildren();work(load);};el('market').onchange=()=>{message('');el('llms-draft').textContent='';draw();gate();};el('reload').onclick=()=>work(load);el('generate').onclick=()=>work(generate,'اتجهزت مسودة الأسئلة. راجع كل سؤال واحفظ موافقتك.');el('identity').onsubmit=e=>{e.preventDefault();const f=e.target.elements,lines=v=>v.split('\n').map(x=>x.trim()).filter(Boolean);work(async()=>{await request('identity',{aliases:lines(f.aliases.value),profile_urls:lines(f.profiles.value),identity_version:Number(data?.identity_version||0)});await load();},'تم حفظ هوية الشركة. راجع الأسئلة واحفظ موافقتك عليها من جديد.');};el('llms').onclick=()=>work(async()=>{const r=await request('llms',{});el('llms-draft').textContent=(r.draft||'')+'\n\n'+(r.note||'راجع المسودة قبل النشر.');},'المسودة جاهزة للمراجعة، ولم يتم نشرها.');work(load);
};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();})();
</script>
